#!/usr/bin/env python3
"""DateDawg: make inbound demand (likes received per calendar week) the Combine
headline, ranked against a lognormal fitted to SwipeStats' published Hinge
like-concentration figures. Outbound match-back rank stays visible as the
secondary number. Idempotent; run from repo root or work/."""
import os, re, sys
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
P = os.path.join(ROOT, "datedawg.html")
s = open(P, encoding="utf-8").read()
MARK = "DEMAND_BENCH"
if MARK in s:
    print("already patched"); sys.exit(0)

def rep(old, new):
    global s
    assert s.count(old) == 1, ("anchor count != 1", old[:80], s.count(old))
    s = s.replace(old, new)

# 1. constants + engine, right after the outbound benchmark source block
rep('    bias:"self-selected uploaders; gender self-reported; the direction of selection bias is unknown"};\n', '    bias:"self-selected uploaders; gender self-reported; the direction of selection bias is unknown"};\n  /* Inbound demand benchmark. SwipeStats publishes two things about likes RECEIVED by men on\n     Hinge: an average of about 3-5 per week, and a concentration table (top 1% of men get\n     16.4% of all likes, top 10% get 58%, bottom 50% get 4.3%). No percentile table is\n     published, so a lognormal is FITTED to the top-10% share; that is a model, labelled as\n     one. The mean is unknown inside 3-5, so the rank is reported as a band, not a point. */\n  var DEMAND_BENCH={\n    publisher:"SwipeStats.io",work:"Hinge Statistics 2026 / How Many Likes a Day on Hinge",\n    url:"https://www.swipestats.io/blog/hinge-statistics",retrieved:"2026-09-09",\n    platform:"Hinge",population:"all men on Hinge — every age, every city; no age or city split is published",\n    measure:"likes received per calendar week; timestamps are when the subject acted on the like, so queue drains shift arrival dates",\n    mean:{lo:3,mid:4,hi:5},topShare:{p:10,share:.58},published:{top1:.164,top10:.58,bottom50:.043},\n    fit:"lognormal; sigma solved from the top-10% share, mean anchored at 3, 4 and 5 likes/week",\n    womenReason:"SwipeStats publishes no distribution of likes received by women beyond the 99+ cap, so no rank exists",\n    sigma:null};\n  DEMAND_BENCH.sigma=Phinv(.9)-Phinv(1-DEMAND_BENCH.topShare.share);\n  function demandAnchors(mean){var s=DEMAND_BENCH.sigma,mu=Math.log(mean||DEMAND_BENCH.mean.mid)-s*s/2;\n    return [5,10,25,50,75,90,95,99].map(function(p){return [p,Math.exp(mu+s*Phinv(p/100))];});}\n  function demandPct(perWeek,mean){var s=DEMAND_BENCH.sigma,mu=Math.log(mean)-s*s/2;\n    return Math.max(0,Math.min(100,100*Phi((Math.log(perWeek)-mu)/s)));}\n  function demandRank(perWeek,sex){\n    if(normalizeSex(sex)==="women")return {available:false,reason:DEMAND_BENCH.womenReason};\n    if(!(perWeek>0))return null;\n    var m=DEMAND_BENCH.mean;\n    /* a higher assumed average pushes the subject DOWN the distribution */\n    return {available:true,perWeek:perWeek,p:demandPct(perWeek,m.mid),\n         band:[demandPct(perWeek,m.hi),demandPct(perWeek,m.lo)],means:m,sigma:DEMAND_BENCH.sigma,\n         anchors:demandAnchors(m.mid),source:DEMAND_BENCH,modelled:true};}\n  /* inbound likes acted on inside [from,to], per calendar week — NOT per active day, because\n        likes accumulate while the subject is away and get stamped when the queue is drained. */\n  function demand(R,from,to,sex){\n    from=Math.max(R.minT,+from||R.minT);to=Math.min(R.maxT,+to||R.maxT);\n    var n=0,acc=0;R.ins.forEach(function(i){if(i.t>=from&&i.t<=to){n++;acc+=i.acc;}});\n    var weeks=Math.max(1,(to-from)/(7*864e5)),perWeek=n/weeks,sufficient=n>=MIN_N&&weeks>=4;\n    return {from:from,to:to,n:n,accepted:acc,weeks:weeks,perWeek:perWeek,sufficient:sufficient,\n         rank:sufficient?demandRank(perWeek,sex):null,\n         insufficientReason:sufficient?null:(n<MIN_N?"fewer than "+MIN_N+" inbound likes in this period":"period shorter than 4 weeks"),\n         caveats:["Demand is modelled on a fitted lognormal, not read off a published table.",\n          "Reference is all men on Hinge; age and city are not in the benchmark.",\n          "Timestamps are when you acted on the like, not when it arrived.",\n          "Visibility features (paid queue view, active liking) raise inbound; some change is exposure, not desirability."]};}\n')

# 2. metrics carries demand from the cut through the latest export date
rep('      rankAdj:Aadj.n&&sex?rank(Aadj.k/Aadj.n,age,sex):null,',
    '      demand:demand(R,cut,R.maxT,sex),\n      rankAdj:Aadj.n&&sex?rank(Aadj.k/Aadj.n,age,sex):null,')

# 3. exports
rep('\n    pctOn:pctOn,density:density,ridgePath:ridgePath,\n', '\n    pctOn:pctOn,density:density,ridgePath:ridgePath,\n    demand:demand,demandRank:demandRank,demandAnchors:demandAnchors,DEMAND_BENCH:DEMAND_BENCH,\n')

# 4. snapshot
rep('      inbound:M.inbound,\n      selectivity:', '      inbound:M.inbound,\n      demand:M.demand?{n:M.demand.n,weeks:M.demand.weeks,per_week:M.demand.perWeek,\n           rank:M.demand.rank&&M.demand.rank.available?{percentile:M.demand.rank.p,band:M.demand.rank.band,\n             means_assumed:M.demand.rank.means,sigma:M.demand.rank.sigma,modelled:true,source:DEMAND_BENCH}:null,\n           insufficient:M.demand.insufficientReason,caveats:M.demand.caveats}:null,\n      selectivity:')

# 5. rank windows carry demand (selected window uses the dashboard dates)
rep('      return {id:"selected",from:S.from,to:S.to,M:{},S:S,primary:primary,primaryLabel:"observed dashboard match-back rate"};',
    '      return {id:"selected",from:S.from,to:S.to,M:{},S:S,primary:primary,primaryLabel:"observed dashboard match-back rate",demand:DD.demand(R,S.from,S.to,BENCHMARK_SEX)};')
rep('    return {id:RANK_RANGE,from:from,to:to,M:DD.metrics(R,from),S:DD.timeSeries(R,from,to,"month")};',
       '    /* demand needs no maturation window: preset periods are trailing spans through the\n         latest export date, so "1 year" of demand is the 52 weeks ending at the export. */\n      var span={"1y":364,"6m":182,"1m":29}[RANK_RANGE];\n      return {id:RANK_RANGE,from:from,to:to,M:DD.metrics(R,from),S:DD.timeSeries(R,from,to,"month"),\n        demand:DD.demand(R,span?R.maxT-span*DAY:R.minT,R.maxT,BENCHMARK_SEX)};')

# 6. verdict: demand headline, match-back secondary
a = s.index("  function verdict(M,R,W){")
b = s.index("  function marketBoundaryGuide(){")
old_verdict = s[a:b]
assert "THE COMBINE" in old_verdict
new_verdict = '  function verdict(M,R,W){\n    var period={selected:"DASHBOARD RANGE",all:"OVERALL", "1y":"1 YEAR", "6m":"6 MONTHS", "1m":"1 MONTH"}[W.id]||W.id,\n        primary=W.S.matureLikes>=DD.MIN_N&&(W.primary||M.rankStd||M.rankAdj),\n        method=W.primary?"OBSERVED":M.rankStd?"VOLUME-STANDARDIZED":"OBSERVED",\n        D=W.demand||null,DR=D&&D.rank&&D.rank.available?D.rank:null,\n        tierOf=function(p){return p>=95?\'Elite tier\':p>=90?\'Top 10%\':p>=80?\'Top 20%\':p>=60?\'Above the pack\':p>=40?\'In the pack\':\'Long-shot territory\';},\n        wk=function(x){return (Math.round(x*10)/10).toFixed(1);},\n        top=\'<div class="vtop">THE COMBINE · READ \'+num(R.records)+\' CONNECTIONS · \'+iso(R.minT).slice(0,4)+\'–\'+iso(R.maxT).slice(0,4)+\' · <b>NOTHING LEFT THIS PAGE</b></div>\';\n    if(!primary&&!DR)return \'<section class="verdict insufficient" id="verdict">\'+top.replace(\'THE COMBINE · \',\'\')+\'<div class="vcore"><div class="vlede">\'+esc(period)+\n      \' · \'+iso(W.from)+\' → \'+iso(W.to)+\'</div><div class="vnum">—</div><div class="vsub">NOT ENOUGH TO RANK THIS PERIOD\'+(D&&D.insufficientReason?\' · \'+esc(D.insufficientReason.toUpperCase()):\'\')+\'</div></div><div class="vchips"><span class="vchip">PERIOD <b>\'+esc(period)+\n      \'</b></span><span class="vchip">MATURE LIKES <b>\'+num(W.S.matureLikes)+\'</b></span><span class="vchip">INBOUND LIKES <b>\'+num(D?D.n:0)+\'</b></span></div><div class="vcue" id="vcue">↓ TRY A LONGER PERIOD BELOW</div></section>\';\n    var svgW=1000,svgH=200,ridge,pin,axes,lede,numHtml,tier,plain,sub,aria;\n    if(DR){\n      var anchors=DR.anchors,rp=DD.ridgePath(anchors,svgW,svgH);\n      pin=Math.max(1,Math.min(99,(Math.log(DR.perWeek)-rp.lo)/rp.span*100));ridge=rp.d;\n      axes=[5,50,90,99].map(function(p){var a=anchors.filter(function(x){return x[0]===p;})[0];return (p===50?\'MEDIAN\':\'p\'+p)+\' · \'+(a?wk(a[1]):\'—\')+\'/wk\';});\n      aria=\'Fitted distribution of likes received per week by men on Hinge\';\n      lede=\'INBOUND DEMAND · ALL MEN ON HINGE · MODELLED\';\n      numHtml=Math.round(DR.p)+\'<i>th</i>\';tier=tierOf(DR.p);\n      plain=\'About <b>\'+wk(DR.perWeek)+\' women a week</b> liked you before you did anything. On SwipeStats’ published like-concentration that lands between the <b>\'+ordinal(DR.band[0])+\' and \'+ordinal(DR.band[1])+\' percentile</b> of men on Hinge, depending on whether the average man receives 3, 4 or 5 likes a week. Age and city are not in the reference.\';\n        sub=\'<em>\'+wk(DR.perWeek)+\'</em> INBOUND LIKES / WEEK · \'+num(D.n)+\' OVER \'+wk(D.weeks)+\' WEEKS · \'+iso(D.from)+\' → \'+iso(D.to);\n   } else {\n        var head=primary.band||primary.all,panchors=primary.band?primary.anchorsBand:primary.anchors,prp=DD.ridgePath(panchors,svgW,svgH);\n        pin=Math.max(1,Math.min(99,(Math.log(primary.rate)-prp.lo)/prp.span*100));ridge=prp.d;\n        axes=[5,50,90,99].map(function(p){var a=panchors.filter(function(x){return x[0]===p;})[0];return (p===50?\'MEDIAN\':\'p\'+p)+\' · \'+(a?pct(a[1]):\'—\');});\n        aria=\'Published \'+primary.sex+\' match-rate distribution\';\n        lede=(primary.band?\'AMONG \'+primary.sex.toUpperCase()+\' \'+esc(primary.bandLabel)+\' · YOUR COHORT\':\'OVERALL · ALL \'+primary.sex.toUpperCase());\n        numHtml=Math.round(head.p)+\'<i>th</i>\';tier=tierOf(head.p);\n        plain=\'You outperform about <b>\'+Math.max(0,Math.min(99,Math.round(head.p)-1))+\' of every 100</b> \'+primary.benchmark.people+\' in this external reference ecosystem.\'+(D&&D.rank&&D.rank.available===false?\' No inbound-demand rank: \'+esc(D.rank.reason)+\'.\':\'\');\n        sub=\'<em>\'+pct(primary.rate)+\'</em> \'+method+\' RECIPROCAL ACCEPTANCE\';\n   }\n   var lift=M.std&&M.std.valid&&M.std.lift!=null?(M.std.lift>0?\'+\':\'\')+(100*M.std.lift).toFixed(0)+\'%\':\'Not available\',\n         mbHead=primary?(primary.band||primary.all):null,\n         matchBack=primary?\'<div class="vmetric"><b>p\'+Math.round(mbHead.p)+\' · \'+pct(primary.rate)+\'</b><span>Match-back rank · \'+method.toLowerCase()+\' reciprocal acceptance · \'+num(W.S.matureMatches)+\' / \'+num(W.S.matureLikes)+\' matured likes</span></div>\':\n           \'<div class="vmetric"><b>—</b><span>Match-back rank · fewer than \'+DD.MIN_N+\' matured likes</span></div>\',\n       demandMetric=DR?\'<div class="vmetric"><b>\'+ordinal(DR.band[0])+\'–\'+ordinal(DR.band[1])+\'</b><span>Demand rank band · average man assumed at 5 / 4 / 3 likes a week</span></div>\':\n           \'<div class="vmetric"><b>—</b><span>Demand rank · \'+esc(D&&D.rank&&D.rank.available===false?D.rank.reason:(D&&D.insufficientReason)||\'unavailable\')+\'</span></div>\';\n   return \'<section class="verdict play" id="verdict">\'+top+\'<div class="vcore"><div class="vlede">\'+lede+\'</div>\'+\n     \'<div class="vnum">\'+numHtml+\'</div><div class="vtier">\'+tier+\'</div><p class="vplain">\'+plain+\'</p><div class="vsub">\'+sub+\'</div></div><div class="vfield"><div class="vridge">\'+\n     \'<svg viewBox="0 0 \'+svgW+\' \'+svgH+\'" preserveAspectRatio="none" aria-label="\'+aria+\'"><defs><linearGradient id="vrg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#2a2118"/><stop offset="1" stop-color="#12100c"/></linearGradient></defs><path d="\'+ridge+\'" fill="url(#vrg)" stroke="#3a3026" stroke-width="1.5"/></svg><div class="vpin" style="left:\'+pin.toFixed(1)+\'%;height:46%"><b>YOU</b></div></div>\'+\n     \'<div class="vaxl">\'+axes.map(function(x){return \'<span>\'+x+\'</span>\';}).join(\'\')+\'</div></div><div class="vchips">\'+\n     demandMetric+matchBack+\'<div class="vmetric"><b>\'+lift+\'</b><span>Volume-standardized change</span></div>\'+\n     (primary&&primary.band?\'<span class="vchip">AMONG \'+primary.sex.toUpperCase()+\' \'+esc(primary.bandLabel)+\' <b>p\'+Math.round(primary.band.p)+\'</b></span><span class="vchip">ALL \'+primary.sex.toUpperCase()+\' <b>p\'+Math.round(primary.all.p)+\'</b></span>\':primary?\'<span class="vchip">ALL \'+primary.sex.toUpperCase()+\' <b>p\'+Math.round(primary.all.p)+\'</b></span>\':\'\')+\n     (M.rankHeavy&&M.heavyAfter&&M.heavyAfter.n>=DD.MIN_N?\'<span class="vchip">HEAVY-DAY CHECK <b>p\'+Math.round((M.rankHeavy.band||M.rankHeavy.all).p)+\'</b></span>\':\'\')+\n       \'<span class="vchip">PERIOD <b>\'+esc(period)+\'</b> · \'+iso(W.from)+\' → \'+iso(W.to)+\'</span>\'+\n       (primary?\'<span class="vchip">n <b>\'+num(primary.benchmark.n)+\'</b> · SWIPESTATS \'+primary.sex.toUpperCase()+\'</span>\':\'\')+\n       (DR?\'<span class="vchip">DEMAND FIT <b>LOGNORMAL σ \'+DR.sigma.toFixed(2)+\'</b> · SWIPESTATS HINGE · TOP 10% = 58% OF LIKES</span>\':\'\')+\n       \'<div class="vcue" id="vcue">↓ ENTER THE ANALYSIS FLOOR</div></div></section>\';}\n\n'
s = s[:a] + new_verdict + s[b:]

# 7. reader notes at the foot of the page
rep('- The Combine is the compact opening answer;',
     '- The Combine’s headline is inbound demand: likes received per calendar week, ranked on a lognormal FITTED to SwipeStats’ published Hinge like-concentration (top 10% of men receive 58% of likes). The average man is assumed at 3, 4 or 5 likes a week, so the rank is a band, not a point; the reference is all men on Hinge with no age or city split; timestamps are when the subject acted, not when the like arrived. It is labelled MODELLED. The outbound match-back rank remains visible beneath it and is the observed number.\n- The Combine is the compact opening answer;')
open(P, "w", encoding="utf-8").write(s)
print("patched", P)
